1	import { Buffer } from 'node:buffer';
2	
3	// The guarded parse of `supabase status -o json` output that the caller has already captured (QA-9 phase 3N gap G5, fix
4	// F4): the same guard as local-stack.mjs's own parse, for verify.mjs, verify-gym.mjs and verify-freezes.mjs. Pure: it
5	// runs nothing, reads and writes nothing, and prints nothing. The output holds keys, so each refusal is fixed text with no
6	// part of the input, no parse detail, no key name and no cause. It decides no target: each suite still asserts API_URL.
7	
8	const NOT_JSON = 'supabase status -o json did not print JSON; its output is not shown because it holds keys';
9	const NOT_OBJECT = 'supabase status -o json did not print a JSON object; its output is not shown because it holds keys';
10	const UNPARSED = Symbol('unparsed');
11	
12	/** JSON.parse's value, or UNPARSED. The parse error is dropped unread, because its message quotes the input. */
13	function parsedOrUnparsed(text) {
14	  try {
15	    return JSON.parse(text);
16	  } catch {
17	    return UNPARSED;
18	  }
19	}
20	
21	/** The JSON object in captured status output: a string, or a Buffer read as UTF-8. Anything else throws a fixed message. */
22	export function parseStatusOutput(output) {
23	  const text = typeof output === 'string' ? output : Buffer.isBuffer(output) ? output.toString('utf8') : undefined;
24	  const value = text === undefined ? UNPARSED : parsedOrUnparsed(text);
25	  if (value === UNPARSED) throw new Error(NOT_JSON);
26	  if (value === null || typeof value !== 'object' || Array.isArray(value)) throw new Error(NOT_OBJECT);
27	  return value;
28	}
