1	import assert from 'node:assert/strict';
2	import { Buffer } from 'node:buffer';
3	import { readFileSync } from 'node:fs';
4	import { test } from 'node:test';
5	import { inspect } from 'node:util';
6	import { parseStatusOutput } from './status-output.mjs';
7	
8	// The wrapper that runs `supabase status -o json` for the three integration suites and passes what it printed to the
9	// guarded parse (QA-9 phase 3N gap G5, fix F4). Every run here is an injected fake: nothing here starts a child process,
10	// reads a real status or reaches Docker, a database or the network. The wrapper's source is checked before it is loaded,
11	// so a change that would run the real command on import fails here instead of running it. The three suites are read as
12	// text and never imported, because importing one runs it against the local stack.
13	
14	const read = (name) => readFileSync(new URL(name, import.meta.url), 'utf8');
15	const occurrences = (text, part) => text.split(part).length - 1;
16	const CHILD_IMPORT = "import { execFileSync } from 'node:child_process';";
17	const DEFAULT_RUN = 'export function readLocalStatus(run = execFileSync) {';
18	const RUN_CALL = "run('pnpm', ['exec', 'supabase', 'status', '-o', 'json'], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] })";
19	const STATUS_COMMAND = ['pnpm', ['exec', 'supabase', 'status', '-o', 'json'], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }];
20	
21	/**
22	 * Throws unless the wrapper can reach the real command only through a call of readLocalStatus with no run: the real
23	 * command is named once, as run's default; run is called once, inside a helper that only readLocalStatus calls; and the
24	 * module never calls readLocalStatus or loads anything else. Checked on the source text, before the module is loaded.
25	 */
26	function assertRunsNothingOnImport(source) {
27	  const lines = source.split('\n');
28	  const specifiers = [...source.matchAll(/\bfrom\s*['"]([^'"]+)['"]|\bimport\s*\(\s*['"]([^'"]+)['"]|^\s*import\s*['"]([^'"]+)['"]/gm)].map((match) => match[1] ?? match[2] ?? match[3]);
29	  assert.deepEqual(specifiers, ['node:child_process', './status-output.mjs'], 'the wrapper loads the child call and the parse helper, nothing else');
30	  assert.deepEqual(lines.filter((line) => line.includes('execFileSync')), [CHILD_IMPORT, DEFAULT_RUN], 'the real command is named only as the default of run');
31	  assert.equal(occurrences(source, 'readLocalStatus'), 1, 'the wrapper never calls itself');
32	  assert.equal(occurrences(source, 'run('), 1, 'run is called in one place');
33	  assert.equal(occurrences(source, RUN_CALL), 1, 'with the exact status command and options');
34	  assert.deepEqual(lines.filter((line) => line.includes('capturedOrFailed')).map((line) => line.trim()), ['function capturedOrFailed(run) {', 'const output = capturedOrFailed(run);'], 'the command runs only from inside readLocalStatus');
35	  assert.doesNotMatch(source, /\b(?:process|console|globalThis|eval|Function)\b|\brequire\s*\(|\bfetch\b|\bspawn|\bexec(?:Sync)?\s*\(|\bfork\s*\(|readFile|writeFile|\bimport\s*\(/, 'nothing else that could run or load anything');
36	}
37	
38	assertRunsNothingOnImport(read('status-command.mjs'));
39	const statusCommand = await import('./status-command.mjs');
40	const { readLocalStatus } = statusCommand;
41	
42	/** Every call here passes a fake run, so run's default, the real command, is never used. */
43	function readWith(run) {
44	  assert.equal(typeof run, 'function', 'a test must pass a fake run');
45	  return readLocalStatus(run);
46	}
47	
48	// Credential-shaped synthetic values, assembled from parts so no literal appears in any file. They are not keys.
49	const SECRET = ['sb', 'secret', 'statuscommand-synthetic-must-never-print-0003'].join('_');
50	const PUBLISHABLE = ['sb', 'publishable', 'statuscommand-synthetic-must-never-print-0004'].join('_');
51	const SENTINEL = ['statuscommand', 'credential', 'sentinel', 'must-never-print-0005'].join('-');
52	const LOOPBACK = 'http://127.0.0.1:55321';
53	const FAILED = 'supabase status -o json failed; its error and output are not shown because they can hold keys';
54	const NOT_JSON = 'supabase status -o json did not print JSON; its output is not shown because it holds keys';
55	const NOT_OBJECT = 'supabase status -o json did not print a JSON object; its output is not shown because it holds keys';
56	// What a thrown value would show if any part of it got through: the failed command line, the start failure, one of its
57	// fields as `name: value`, or a cause or inner errors under inspection.
58	const ORIGINAL_DETAIL = /Command failed|spawnSync|ENOENT|ETIMEDOUT|\b(?:stdout|stderr|output|status|signal|pid|errno|syscall|spawnargs|cause|errors)\s*:|\[cause\]|\[errors\]/;
59	const statusJson = (fields = {}) => JSON.stringify({ API_URL: LOOPBACK, PUBLISHABLE_KEY: PUBLISHABLE, SECRET_KEY: SECRET, ...fields });
60	
61	/** An error shaped like the one a failed status command throws, with synthetic keys in its message, stack, cause and fields. */
62	const commandError = (stdout, fields = {}) => Object.assign(
63	  new Error(`Command failed: pnpm exec supabase status -o json\n${SECRET}`, { cause: new Error(`${SENTINEL} ${PUBLISHABLE}`) }),
64	  { stack: `Error: Command failed ${SECRET}\n    at ${SENTINEL} (file:///${PUBLISHABLE}.mjs:1:1)`, status: 1, signal: null, pid: 4242, output: [null, stdout, `${SENTINEL}`], stdout, stderr: `${SECRET} ${SENTINEL}`, ...fields },
65	);
66	
67	/**
68	 * The error `action` throws, after checking every way it can be shown: its message, its string form, its stack, a full
69	 * inspection, JSON with and without its hidden fields, and a structured clone. None may hold a synthetic key or the
70	 * sentinel, a key name, a URL or any detail of a thrown value, and the error has no field but its fixed message.
71	 */
72	function refusal(action, expected, label) {
73	  let caught;
74	  assert.throws(action, (error) => { caught = error; return true; }, `${label}: must throw`);
75	  assert.equal(Object.getPrototypeOf(caught), Error.prototype, `${label}: a plain Error`);
76	  assert.equal(caught.message, expected, `${label}: the fixed message`);
77	  assert.equal('cause' in caught, false, `${label}: no cause`);
78	  assert.deepEqual(Object.getOwnPropertyNames(caught).filter((name) => name !== 'stack'), ['message'], `${label}: no field but the message`);
79	  assert.deepEqual(Object.getOwnPropertySymbols(caught), [], `${label}: no symbol field`);
80	  const [head, ...frames] = String(caught.stack).split('\n');
81	  assert.equal(head, `Error: ${expected}`, `${label}: the stack starts with the fixed message`);
82	  for (const frame of frames) assert.match(frame, /^\s+at /, `${label}: after the message the stack holds call sites only`);
83	  const shown = [
84	    caught.message,
85	    String(caught),
86	    String(caught.stack),
87	    inspect(caught, { showHidden: true, depth: Infinity }),
88	    JSON.stringify(caught),
89	    JSON.stringify(caught, Object.getOwnPropertyNames(caught)),
90	    inspect(structuredClone(caught), { showHidden: true, depth: Infinity }),
91	  ];
92	  for (const form of shown) {
93	    for (const part of [SECRET, PUBLISHABLE, SENTINEL]) assert.equal(form.includes(part), false, `${label}: a synthetic value is shown`);
94	    assert.doesNotMatch(form, /sb_(?:secret|publishable)_|must-never-print/, `${label}: part of a synthetic value is shown`);
95	    assert.doesNotMatch(form, /API_URL|SECRET_KEY|PUBLISHABLE_KEY|127\.0\.0\.1|localhost/, `${label}: a key name or a URL is shown`);
96	    assert.doesNotMatch(form, ORIGINAL_DETAIL, `${label}: a detail of the thrown value is shown`);
97	  }
98	  return caught;
99	}
100	
101	/** The error readLocalStatus throws when its run throws `thrown`: the fixed refusal, after one exact call, never `thrown`. */
102	function failure(thrown, label) {
103	  const calls = [];
104	  const caught = refusal(() => readWith((...received) => { calls.push(received); throw thrown; }), FAILED, label);
105	  assert.deepEqual(calls, [STATUS_COMMAND], `${label}: one call of the exact command, never retried`);
106	  assert.notEqual(caught, thrown, `${label}: a new error, not the thrown value`);
107	  return caught;
108	}
109	
110	test('a successful run gives the parsed object, from a string or a Buffer, after one call of the exact command and options', () => {
111	  const expected = { API_URL: LOOPBACK, PUBLISHABLE_KEY: PUBLISHABLE, SECRET_KEY: SECRET };
112	  const outputs = [statusJson(), `${statusJson()}\n`, Buffer.from(`${statusJson()}\n`, 'utf8')];
113	  for (const [index, output] of outputs.entries()) {
114	    const calls = [];
115	    const value = readWith((...received) => { calls.push(received); return output; });
116	    assert.deepEqual(value, expected, `output ${index}: the status object`);
117	    assert.deepEqual(calls, [STATUS_COMMAND], `output ${index}: one call, with the command, arguments and options the suites ran, nothing added`);
118	  }
119	});
120	
121	test("a successful run's output goes to parseStatusOutput unchanged: the helper's value, or its own fixed refusal", () => {
122	  const values = [statusJson(), JSON.stringify({ API_URL: 'http://localhost:55321' }), '{}'];
123	  for (const [index, output] of values.entries()) {
124	    assert.deepEqual(readWith(() => output), parseStatusOutput(output), `value ${index}: the helper's value, not rewritten; each suite still asserts its target`);
125	  }
126	  const refused = [
127	    [statusJson().slice(0, -1), NOT_JSON], // cut before its closing brace
128	    [`{"API_URL":"${LOOPBACK}","SECRET_KEY":${SECRET}}`, NOT_JSON], // the secret unquoted, right at the failing position
129	    [Buffer.from(`Starting the CLI\n${statusJson()}`, 'utf8'), NOT_JSON], // a notice line before the object
130	    [undefined, NOT_JSON], // a run that returned nothing
131	    [`[${statusJson()}]`, NOT_OBJECT], // an array, not an object
132	    [JSON.stringify(SECRET), NOT_OBJECT], // a bare string
133	  ];
134	  for (const [index, [output, expected]] of refused.entries()) {
135	    refusal(() => readWith(() => output), expected, `refused ${index}: the helper's refusal, not the run-failure message`);
136	  }
137	});
138	
139	test('a failed command throws one new fixed error that shows no message, stack, cause or field of the error it threw', () => {
140	  const thrown = [
141	    ['a failed command, its output a string', commandError(statusJson())],
142	    ['a failed command, its output a Buffer', commandError(Buffer.from(statusJson(), 'utf8'))],
143	    ['a timed-out command', commandError(statusJson(), { code: 'ETIMEDOUT', status: null, signal: 'SIGTERM' })],
144	    ['a command that could not start', Object.assign(new Error(`spawnSync pnpm ENOENT ${SENTINEL}`), { errno: -2, code: 'ENOENT', syscall: 'spawnSync pnpm', path: SECRET, spawnargs: ['exec', 'supabase', 'status', '-o', 'json', SECRET], stdout: null, stderr: null })],
145	    ['an AggregateError around a failed command', new AggregateError([commandError(statusJson())], `${SENTINEL} ${SECRET}`)],
146	    ['a plain object with output and string forms', { message: SECRET, stdout: statusJson(), output: [null, statusJson(), null], toString: () => SECRET, toJSON: () => SECRET }],
147	    ['a Buffer of status output', Buffer.from(statusJson(), 'utf8')],
148	  ];
149	  const errors = thrown.map(([label, value]) => failure(value, label));
150	  assert.equal(new Set(errors).size, errors.length, 'every failure throws a new error, never a shared one');
151	});
152	
153	test('a thrown primitive gives the same fixed error and shows nothing of the value', () => {
154	  const primitives = [SECRET, SENTINEL, statusJson(), '', undefined, null, 0, 55321, true, 4242n, Symbol(SECRET)];
155	  for (const [index, value] of primitives.entries()) failure(value, `thrown primitive ${index}`);
156	});
157	
158	/** A thrown value that records every read: a getter for each field or conversion a wrapper might touch, each throwing keys. */
159	function watchedGetters(touched) {
160	  const keys = ['message', 'stack', 'name', 'cause', 'code', 'status', 'signal', 'pid', 'output', 'stdout', 'stderr', 'errors', 'constructor', 'toString', 'valueOf', 'toJSON', 'then', Symbol.toPrimitive, Symbol.toStringTag, inspect.custom];
161	  const value = Object.create(Error.prototype);
162	  for (const key of keys) {
163	    Object.defineProperty(value, key, { enumerable: true, get() { touched.push(String(key)); throw new Error(`${SECRET} ${SENTINEL}`); } });
164	  }
165	  return value;
166	}
167	
168	/** A proxy whose handler records every trap looked up, so any operation on it is seen, then throws keys. */
169	function watchedProxy(touched, target) {
170	  const traps = new Proxy({}, { get: (_, trap) => { touched.push(`trap ${String(trap)}`); return () => { throw new Error(`${SECRET} ${SENTINEL}`); }; } });
171	  return new Proxy(target, traps);
172	}
173	
174	test('the thrown value is never read: getters on every field and proxies that watch every trap see no access', () => {
175	  const cases = [
176	    ['getters on every field', (touched) => watchedGetters(touched)],
177	    ['a proxy over an empty object', (touched) => watchedProxy(touched, {})],
178	    ['a proxy over a failed-command error', (touched) => watchedProxy(touched, commandError(statusJson()))],
179	  ];
180	  for (const [label, build] of cases) {
181	    const touched = [];
182	    failure(build(touched), label);
183	    assert.deepEqual(touched, [], `${label}: nothing read the thrown value`);
184	  }
185	});
186	
187	test('the wrapper exports readLocalStatus alone, binds no caught value, and parses through the helper after its catch', () => {
188	  assert.deepEqual(Object.keys(statusCommand), ['readLocalStatus']);
189	  const source = read('status-command.mjs');
190	  assert.equal(occurrences(source, 'catch {'), 1, 'one catch, and it binds nothing');
191	  assert.doesNotMatch(source, /catch\s*\(/, 'no catch binds the thrown value');
192	  assert.doesNotMatch(source, /\.(?:cause|stdout|stderr|output|message|stack|status|code)\b/, 'the wrapper reads no field of anything thrown');
193	  assert.equal(occurrences(source, 'throw new Error(FAILED);'), 1, 'the run failure throws the fixed message alone, with no cause');
194	  assert.equal(occurrences(source, 'parseStatusOutput('), 1, 'one parse, through the helper');
195	  assert.equal(source.split('\n').filter((line) => line.trim() === 'return parseStatusOutput(output);').length, 1, "what the command printed goes straight to the helper");
196	  assert.ok(source.indexOf('return parseStatusOutput(output);') > source.indexOf('catch {'), 'the parse sits outside the catch, so its refusals are kept');
197	  assert.doesNotMatch(source, /JSON\.parse/, 'no unguarded parse');
198	});
199	
200	const WRAPPER_IMPORT = "import { readLocalStatus } from './status-command.mjs';";
201	const SUITES = Object.freeze([
202	  { file: 'verify.mjs', name: 'status', check: "assert.equal(status.API_URL, 'http://127.0.0.1:55321', 'Refusing to run against any other backend');" },
203	  { file: 'verify-gym.mjs', name: 'config', check: "assert.equal(config.API_URL, 'http://127.0.0.1:55321', 'Tests only run on the isolated local stack');" },
204	  { file: 'verify-freezes.mjs', name: 'config', check: "assert.equal(config.API_URL, 'http://127.0.0.1:55321', 'Tests only run on the isolated local stack');" },
205	]);
206	
207	test('all three suites read status through the wrapper alone: the direct command and its imports are gone, and the loopback assertion follows unchanged (read as text, never imported)', () => {
208	  for (const { file, name, check } of SUITES) {
209	    const source = read(file);
210	    const lines = source.split('\n');
211	    assert.equal(lines.filter((line) => line === WRAPPER_IMPORT).length, 1, `${file}: imports the wrapper once`);
212	    const call = lines.indexOf(`const ${name} = readLocalStatus();`);
213	    assert.notEqual(call, -1, `${file}: reads status through the wrapper, which runs the real command by default`);
214	    assert.equal(lines[call + 1], check, `${file}: the loopback assertion follows at once, unchanged`);
215	    assert.equal(occurrences(source, check), 1, `${file}: one loopback assertion`);
216	    assert.equal(occurrences(source, 'readLocalStatus('), 1, `${file}: status is read once`);
217	    assert.doesNotMatch(source, /node:child_process|execFileSync|\bspawn|'supabase', 'status'/, `${file}: the direct status command and its child import are removed`);
218	    assert.doesNotMatch(source, /parseStatusOutput|status-output\.mjs/, `${file}: the now-unused parse import is removed; the wrapper parses`);
219	  }
220	});
