7	
8	// The guarded parse of `supabase status -o json` output that a caller has already captured (QA-9 phase 3N gap G5, fix
9	// F4). Pure: every input is a synthetic string or Buffer built here. Nothing here runs a command, reads a real status or
10	// reaches Docker, a database or the network. The three integration suites are read as text and never imported, because
11	// importing one runs it against the local stack.
12	const { parseStatusOutput } = statusOutput;
13	
14	// Credential-shaped synthetic values, assembled from parts so neither literal appears in any file. They are not keys.
15	const SECRET = ['sb', 'secret', 'statusparse-synthetic-must-never-print-0001'].join('_');
16	const PUBLISHABLE = ['sb', 'publishable', 'statusparse-synthetic-must-never-print-0002'].join('_');
17	const LOOPBACK = 'http://127.0.0.1:55321';
18	const NOT_JSON = 'supabase status -o json did not print JSON; its output is not shown because it holds keys';
19	const NOT_OBJECT = 'supabase status -o json did not print a JSON object; its output is not shown because it holds keys';
20	// What a raw JSON.parse error, or one attached as a cause, would show: V8 names the failure and quotes the input near it.
21	const PARSE_DETAIL = /SyntaxError|is not valid JSON|in JSON at position|Unexpected token|Unexpected end of JSON|Unexpected non-whitespace|Unterminated string|Bad control character|\[cause\]/;
22	const statusJson = (fields = {}) => JSON.stringify({ API_URL: LOOPBACK, PUBLISHABLE_KEY: PUBLISHABLE, SECRET_KEY: SECRET, ...fields });
23	const read = (name) => readFileSync(new URL(name, import.meta.url), 'utf8');
