27	 * The error parseStatusOutput throws for `input`, after checking every way it can be shown: its message, its string form,
28	 * its stack and a full inspection. None may hold the synthetic credentials, a key name, the input's URL, a parse detail
29	 * or a cause, and the error carries no field but its fixed message.
30	 */
31	function refusal(input, expected, label) {
32	  let caught;
33	  assert.throws(() => parseStatusOutput(input), (error) => { caught = error; return true; }, `${label}: must throw`);
34	  assert.equal(Object.getPrototypeOf(caught), Error.prototype, `${label}: a plain Error, not the parse error`);
35	  assert.equal(caught.message, expected, `${label}: the fixed message`);
36	  assert.equal('cause' in caught, false, `${label}: no cause`);
37	  assert.deepEqual(Object.getOwnPropertyNames(caught).filter((name) => name !== 'stack'), ['message'], `${label}: no field but the message`);
38	  const [head, ...frames] = String(caught.stack).split('\n');
39	  assert.equal(head, `Error: ${expected}`, `${label}: the stack starts with the fixed message`);
40	  for (const frame of frames) assert.match(frame, /^\s+at /, `${label}: after the message the stack holds call sites only`);
41	  for (const shown of [caught.message, String(caught), String(caught.stack), inspect(caught, { showHidden: true, depth: Infinity })]) {
42	    assert.equal(shown.includes(SECRET), false, `${label}: the synthetic secret is shown`);
43	    assert.equal(shown.includes(PUBLISHABLE), false, `${label}: the synthetic publishable key is shown`);
44	    assert.doesNotMatch(shown, /sb_(secret|publishable)_/, `${label}: part of a synthetic key is shown`);
45	    assert.doesNotMatch(shown, /API_URL|SECRET_KEY|PUBLISHABLE_KEY|127\.0\.0\.1/, `${label}: a key name or the input's URL is shown`);
46	    assert.doesNotMatch(shown, PARSE_DETAIL, `${label}: a parse detail or a cause is shown`);
47	  }
