51	test('a JSON object, as a string or as a Buffer, comes back exactly as JSON.parse gives it', () => {
52	  const expected = { API_URL: LOOPBACK, PUBLISHABLE_KEY: PUBLISHABLE, SECRET_KEY: SECRET };
53	  assert.deepEqual(parseStatusOutput(statusJson()), expected);
