57	  assert.deepEqual(parseStatusOutput(bytes), expected, 'a Buffer is read as UTF-8');
58	  assert.deepEqual(bytes, before, 'the Buffer is only read, never changed');
59	  const nested = { API_URL: LOOPBACK, NESTED: { list: [1, 'two', null], flag: true }, COUNT: 3 };
60	  assert.deepEqual(parseStatusOutput(JSON.stringify(nested, null, 2)), nested);
61	  assert.deepEqual(parseStatusOutput(Buffer.from(JSON.stringify(nested), 'utf8')), nested);
